function grab(raw) {
  const s = String(raw || '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a < 0 || b < 0) return {};
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return {}; }
}
const src = $input.first().json;
const orig = $('Normalize Tender').first().json || {};
const ai = grab(src.output);
const join = (v) => Array.isArray(v) ? v.join('; ') : (v ? String(v) : '');
const rec = String(ai.recommendation || 'needs_review').toLowerCase().trim();
const dl = ['low', 'medium', 'high'].includes(String(ai.deadline_risk || '').toLowerCase()) ? String(ai.deadline_risk).toLowerCase() : 'medium';
return [{
  json: {
    ...orig, ...src,
    fit_score: typeof ai.fit_score === 'number' ? ai.fit_score : 0,
    recommendation: (rec === 'bid' || rec === 'no_bid') ? rec : 'needs_review',
    strengths: join(ai.strengths),
    risks: join(ai.risks),
    key_requirements: join(ai.key_requirements),
    deadline_risk: dl,
    ai_summary: ai.summary || '',
    status: 'Tracking'
  }
}];

const rows = $input.all();
const now = new Date();
const lines = [];
let kept = 0;
for (const r of rows) {
  const j = r.json || {};
  const due = j.due_date ? new Date(String(j.due_date) + 'T00:00:00') : null;
  if (!due || isNaN(due.getTime())) continue;
  const days = Math.floor((due - now) / 86400000);
  if (days < 0 || days > 14) continue;
  kept++;
  lines.push('- ' + (j.tender_title || 'Untitled') + ' (fit ' + (j.fit_score != null ? j.fit_score : '?') + '/100, ' + (j.recommendation || 'unknown') + ') due ' + String(j.due_date));
}
const text = kept === 0
  ? 'No tracked tenders are due in the next 14 days.'
  : 'Tenders being tracked with deadlines in the next 14 days:\n\n' + lines.join('\n') + '\n\nOpen the tracker sheet to review each one and decide next steps.';
return [{ json: { digest_text: text, digest_count: kept } }];
